#!/usr/bin/env node
// Offline-model CER benchmark for Figaro's hearing.
//
//   node scripts/asr-cer-bench.mjs                     # all installed models
//   node scripts/asr-cer-bench.mjs --model=paraformer
//   node scripts/asr-cer-bench.mjs --noise=/tmp/ambient-10s-45.raw
//
// Corpus: models/bench-audio (44 TTS sentences, ground truth in manifest.json,
// generated by scripts/gen-asr-bench-audio.mjs; git-ignored).
//
// Channel conditions:
//   clean                      the TTS wav as-is
//   snr20 / snr10 / snr5       real microphone noise (recorded from the actual
//                              mic at the calibrated 45% gain) mixed at the
//                              given SNR
//   tailcut                    clean audio with the last 200 ms trimmed
//                              (sensitivity to an endCapture that fires too early)
//
// Metrics: normalised CER (punctuation removed), raw CER, decode latency
// (median), model size, RSS delta.
//
// Models searched (first existing wins):
//   paraformer : models/asr-offline (model.int8.onnx + tokens.txt)
//   sensevoice : models/asr-offline-sensevoice (model.int8.onnx + tokens.txt)
//                or /tmp/figaro-models-dl/x/sherpa-onnx-sense-voice-*/ 
//
// Exit code 0 always (it is a measurement tool); the table is the output.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { createOfflineAsr } from '../src/voice/asr/recognizers.js';
import { loadConfig } from '../src/config.js';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');
const CORPUS = path.join(ROOT, 'models', 'bench-audio');
const args = process.argv.slice(2);
const argVal = (name, dflt) => {
  const a = args.find((x) => x.startsWith(`--${name}=`));
  return a ? a.slice(name.length + 3) : dflt;
};
const onlyModel = argVal('model', null);
// fair CER comparison: keep Chinese numerals (ITN=0) unless overridden
if (!process.argv.includes('--itn=1')) process.env.FIGARO_SENSEVOICE_ITN = '0';
const noisePath = argVal('noise', '/tmp/ambient-10s-45.raw');

// ---------- audio io ----------
function readWavSamples(file) {
  const b = fs.readFileSync(file);
  let off = 12;
  let fmt = null;
  let ds = 0;
  let dl = 0;
  while (off + 8 <= b.length) {
    const id = b.toString('ascii', off, off + 4);
    const size = b.readUInt32LE(off + 4);
    const body = off + 8;
    if (id === 'fmt ') fmt = { ch: b.readUInt16LE(body + 2), sr: b.readUInt32LE(body + 4) };
    if (id === 'data') { ds = body; dl = size; }
    off = body + size + (size % 2);
  }
  const n = Math.floor(dl / 2 / fmt.ch);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) out[i] = b.readInt16LE(ds + i * 2 * fmt.ch) / 32768;
  return out;
}
function readRawSamples(file) {
  const b = fs.readFileSync(file);
  const n = Math.floor(b.length / 2);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) out[i] = b.readInt16LE(i * 2) / 32768;
  return out;
}
const rms = (a) => { let s = 0; for (const v of a) s += v * v; return Math.sqrt(s / Math.max(1, a.length)); };
const peak = (a) => { let p = 0; for (const v of a) p = Math.max(p, Math.abs(v)); return p; };

const noiseBed = fs.existsSync(noisePath) ? readRawSamples(noisePath) : null;

/** Mix a noise bed into speech at the requested SNR (noise scaled to speech RMS). */
function addNoise(speech, snrDb) {
  if (!noiseBed || noiseBed.length === 0) return speech;
  const out = new Float32Array(speech.length);
  const sRms = rms(speech) || 1e-4;
  const nRms = rms(noiseBed) || 1e-4;
  const target = sRms / 10 ** (snrDb / 20);
  const scale = target / nRms;
  for (let i = 0; i < speech.length; i++) out[i] = speech[i] + noiseBed[i % noiseBed.length] * scale;
  const p = peak(out);
  if (p > 0.95) { const g = 0.95 / p; for (let i = 0; i < out.length; i++) out[i] *= g; }
  return out;
}
function trimTail(samples, ms) {
  const n = Math.max(0, samples.length - Math.round((16000 * ms) / 1000));
  return samples.subarray(0, n);
}

// ---------- CER ----------
const PUNCT = /[\s，。！？、,.!?;；:：…~～"'“”‘’()（）【】《》<>—\-]/g;
const norm = (s) => String(s ?? '').replace(PUNCT, '').toLowerCase();
function levenshtein(a, b) {
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
}

// ---------- models ----------
function modelCandidates() {
  const list = [];
  const config = loadConfig();
  const paraDir = path.resolve(ROOT, config.asr.offlineModelDir);
  list.push({ name: 'paraformer-zh-int8 (现役)', kind: 'paraformer', dir: paraDir });
  const svDirCandidates = [
    path.join(ROOT, 'models', 'asr-offline-sensevoice'),
    ...fs.readdirSync('/tmp/figaro-models-dl').filter((d) => d.startsWith('sherpa-onnx-sense-voice')).map((d) => path.join('/tmp/figaro-models-dl', d)),
  ];
  for (const dir of svDirCandidates) {
    if (fs.existsSync(dir)) { list.push({ name: 'SenseVoice-small-int8', kind: 'sense-voice', dir }); break; }
  }
  return list.filter((m) => !onlyModel || m.name.toLowerCase().includes(onlyModel.toLowerCase()));
}

function dirSize(dir) {
  let total = 0;
  try {
    for (const f of fs.readdirSync(dir)) {
      const st = fs.statSync(path.join(dir, f));
      total += st.isFile() ? st.size : 0;
    }
  } catch { /* ignore */ }
  return total;
}

// ---------- run ----------
if (!fs.existsSync(CORPUS)) {
  console.error(`corpus missing: ${CORPUS}\n先运行: node scripts/gen-asr-bench-audio.mjs`);
  process.exit(2);
}
const manifest = JSON.parse(fs.readFileSync(path.join(CORPUS, 'manifest.json'), 'utf8'));
const audio = manifest.map((m) => ({ ...m, samples: readWavSamples(path.join(CORPUS, m.file)) }));
console.log(`corpus: ${audio.length} 句, ${(audio.reduce((n, a) => n + a.samples.length, 0) / 16000).toFixed(1)}s`);
console.log(`noise bed: ${noiseBed ? `${noisePath} (${(noiseBed.length / 16000).toFixed(1)}s, RMS ${Math.round(rms(noiseBed) * 32768)})` : '无（跳过加噪条件）'}`);

const conditions = [
  { name: 'clean', build: (s) => s },
  ...(noiseBed ? [
    { name: 'snr20', build: (s) => addNoise(s, 20) },
    { name: 'snr10', build: (s) => addNoise(s, 10) },
    { name: 'snr5', build: (s) => addNoise(s, 5) },
  ] : []),
  { name: 'tailcut200ms', build: (s) => trimTail(s, 200) },
];

const results = [];
for (const cand of modelCandidates()) {
  const size = dirSize(cand.dir);
  const rssBefore = process.memoryUsage().rss / 1e6;
  const tLoad = Date.now();
  let rec;
  try {
    rec = createOfflineAsr({ dir: cand.dir, numThreads: 1 });
  } catch (err) {
    console.log(`\n模型 ${cand.name} 加载失败: ${err.message}`);
    continue;
  }
  if (!rec) { console.log(`\n模型 ${cand.name} 不可用（目录不完整）: ${cand.dir}`); continue; }
  const loadMs = Date.now() - tLoad;
  const rssAfterLoad = process.memoryUsage().rss / 1e6;
  console.log(`\n=== ${cand.name} (kind=${rec.kind}, ${(size / 1e6).toFixed(0)} MB, load ${loadMs}ms, RSS +${Math.round(rssAfterLoad - rssBefore)}MB) ===`);
  for (const cond of conditions) {
    const rows = [];
    for (const item of audio) {
      const pcm = cond.build(item.samples);
      const t0 = Date.now();
      const hyp = await rec.transcribe(pcm);
      const ms = Date.now() - t0;
      const refN = norm(item.text);
      const hypN = norm(hyp);
      const cer = levenshtein(hypN, refN) / Math.max(1, refN.length);
      rows.push({ id: item.id, ref: item.text, hyp, cer, ms });
    }
    const meanCer = rows.reduce((n, r) => n + r.cer, 0) / rows.length;
    const sortedMs = rows.map((r) => r.ms).sort((a, b) => a - b);
    const medMs = sortedMs[Math.floor(sortedMs.length / 2)];
    const p90Cer = [...rows].sort((a, b) => a.cer - b.cer)[Math.floor(rows.length * 0.9)]?.cer ?? 0;
    const worst = [...rows].sort((a, b) => b.cer - a.cer).slice(0, 3);
    results.push({ model: cand.name, kind: rec.kind, condition: cond.name, meanCer, p90Cer, medianMs: medMs, rows });
    console.log(`  ${cond.name.padEnd(12)} CER ${(meanCer * 100).toFixed(1)}%  p90 ${(p90Cer * 100).toFixed(1)}%  中位延迟 ${medMs}ms  worst: ${worst.map((w) => `${w.id}=${(w.cer * 100).toFixed(0)}%`).join(', ')}`);
  }
  if (rec.free) rec.free();
}

// comparison table
console.log('\n=== 对比表（CER %，越低越好）===');
const models = [...new Set(results.map((r) => r.model))];
const condNames = [...new Set(results.map((r) => r.condition))];
console.log(['condition'.padEnd(14), ...models.map((m) => m.padEnd(28))].join(' | '));
for (const cond of condNames) {
  const cells = models.map((m) => {
    const r = results.find((x) => x.model === m && x.condition === cond);
    return r ? `${(r.meanCer * 100).toFixed(1)}%`.padEnd(28) : '-'.padEnd(28);
  });
  console.log([cond.padEnd(14), ...cells].join(' | '));
}
console.log('\n__CER_JSON__');
console.log(JSON.stringify(results.map(({ rows, ...rest }) => ({ ...rest, worst: [...rows].sort((a, b) => b.cer - a.cer).slice(0, 5).map((r) => ({ id: r.id, ref: r.ref, hyp: r.hyp, cer: Number(r.cer.toFixed(3)) })) })), null, 2));
